var c=$input.first().json.data||$input.first().json;
var outcome=String(c.outcome||c.responseIntent||'').toLowerCase().trim();
var map={accepted:'accepted',accept:'accepted',contract_ready:'accepted',signed:'accepted',counteroffer:'counteroffer',counter:'counteroffer',rejected:'rejected',reject:'rejected',declined:'rejected',dnc:'dnc',do_not_contact:'dnc',no_response:'no_response',expired:'no_response'};
var normalized=map[outcome]||'unknown';
var terminal=['accepted','rejected','dnc'].indexOf(normalized)!==-1;
return [{json:{...c,normalizedOutcome:normalized,terminalOutcome:terminal}}];

var d=$input.first().json;
var status=String(d.dealStatus||'').toLowerCase();
var protectedState=['closed','cancelled','disputed'].indexOf(status)!==-1;
var unknown=d.normalizedOutcome==='unknown';
var blocked=protectedState||unknown;
var nextState=blocked?status:(d.normalizedOutcome==='accepted'?'contract_ready':d.normalizedOutcome==='counteroffer'?'negotiation':d.normalizedOutcome==='rejected'?'seller_rejected':d.normalizedOutcome==='dnc'?'dnc':status||'negotiation');
return [{json:{...d,blocked,blockedReason:protectedState?'deal_state_protected':unknown?'unknown_outcome':null,nextDealState:nextState}}];
